  'nav.modules' => 'Mô-đun',
  'mod.locked' => 'Tính năng này chưa được bật trên bản chạy này.',
  'mod.lockedAdmin' => 'Mô-đun « {module} » chưa được bật trên bản chạy này. Quý khách có thể bật nó trong bảng quản trị, mục Mô-đun.',
  'mod.comptabilite.label' => 'Kế toán',
  'mod.comptabilite.what' => 'Hệ thống tài khoản, sổ nhật ký, bút toán cân đối, sổ cái và bảng cân đối thử. Một hoá đơn có thể ghi sổ bằng một cú nhấp.',
  'mod.comptabilite.caveat' => 'Ghi sổ nội bộ. Không có bộ hồ sơ thuế, không nộp điện tử: bản xuất bảng cân đối thử chuyển cho kế toán của quý khách.',
  'mod.paie.label' => 'Bộ tính lương',
  'mod.paie.what' => 'Biểu suất đóng góp cấu hình được, tính từ lương gộp sang lương thực nhận, phần người sử dụng lao động và chi phí sử dụng lao động, phiếu lương chi tiết.',
  'mod.paie.caveat' => 'Các mức tỷ lệ là do quý khách nhập: chúng được điền sẵn để tham khảo và cần người phụ trách lương kiểm tra. Không tạo ra bất kỳ tờ khai bắt buộc nào.',
  'mod.facturation-electronique.label' => 'Hoá đơn điện tử',
  'mod.facturation-electronique.what' => 'Kiểm tra các mục bắt buộc theo EN 16931, xuất XML CII (UN/CEFACT) và Factur-X: tệp PDF/A-3 đọc được, mang XML ấy làm đính kèm.',
  'mod.facturation-electronique.caveat' => 'Việc nộp lên nền tảng được công nhận vẫn còn phải làm: nó cần một tài khoản ở nhà cung cấp, không phải một cài đặt ở đây.',
  'mod.stock.label' => 'Kho và mua hàng',
  'mod.stock.what' => 'Mặt hàng, phát sinh nhập và xuất, ngưỡng cảnh báo, và đề nghị mua hàng do quản lý rồi bộ phận điều hành duyệt.',
  'mod.stock.caveat' => 'Kho đơn điểm, định giá theo đơn giá biết đến gần nhất. Không kiểm kê luân phiên, không định giá FIFO hay bình quân gia quyền.',
  'mod.tresorerie.label' => 'Ngân quỹ',
  'mod.tresorerie.what' => 'Tài khoản ngân hàng, phát sinh, đối chiếu khoản thu với hoá đơn, và dự báo dòng tiền mười hai tuần.',
  'mod.tresorerie.caveat' => 'Nhập và nạp thủ công: không thiết lập kết nối ngân hàng nào (PSD2). Số dư là con số quý khách đã nhập, không phải của ngân hàng.',
  'mod.immobilisations.label' => 'Tài sản cố định',
  'mod.immobilisations.what' => 'Sổ tài sản cố định, bảng khấu hao đường thẳng và số dư giảm dần, giá trị còn lại và mức trích trong kỳ.',
  'mod.immobilisations.caveat' => 'Các bảng này là công cụ theo dõi: việc gắn vào sổ kế toán, các cấu phần và khấu hao ưu đãi vẫn thuộc phần của kế toán quý khách.',
  'mod.crm.label' => 'CRM bán hàng',
  'mod.crm.what' => 'Liên hệ, luồng cơ hội, báo giá chuyển được thành hoá đơn, và nhắc việc đến hạn.',
  'mod.crm.caveat' => 'Theo dõi bán hàng nội bộ: không đồng bộ với hộp thư, không tự động hoá tiếp thị.',
