  'bak.archiveHelp' => 'Bản lưu chứa cơ sở dữ liệu — sao chép bằng cơ chế sao lưu trực tuyến của SQLite nên nhất quán ngay cả khi đang ghi — cùng ảnh hồ sơ, CV và két tài liệu. Mỗi tệp mang mã băm, được kiểm tra khi khôi phục.',
