  'bak.whyOffsiteHelp' => 'Bản sao lưu nằm trên chính máy chủ nó bảo vệ thì không bảo vệ gì cả: hỏng đĩa, hỏa hoạn và mã độc tống tiền cuốn đi cả hai. Mỗi bản lưu được gửi tới các đích đang bật ngay khi tạo, và số bản giữ ở đó khớp với thiết lập cục bộ.',
  'bak.destinationNotice' => 'Bản lưu được gửi nguyên trạng: chứa mã băm mật khẩu, khóa xác thực hai lớp và phiếu lương. Hãy chọn đích có quyền truy cập hạn chế ngang với máy chủ này.',
