  'bak.secretsHelp' => 'Các khóa bí mật được mã hóa trong cơ sở dữ liệu bằng khóa dẫn xuất từ khóa phiên, nằm ở tệp riêng: chỉ bản sao cơ sở dữ liệu không tiết lộ chúng. Để trống ô bí mật sẽ giữ nguyên giá trị hiện có.',
