  'bak.restoreHelp' => 'Nội dung cơ sở dữ liệu được thay bằng nội dung bản lưu, từng bảng một, trong một giao dịch duy nhất: ứng dụng vẫn chạy và lỗi giữa chừng không để lại cơ sở dữ liệu ghi dở. Ảnh, CV và tài liệu két được đưa về trạng thái của bản lưu — thứ không có trong đó sẽ bị xóa.',
  'bak.twoExceptions' => 'Hai ngoại lệ có chủ đích: {sessions} không được khôi phục, để bạn không bị đăng xuất giữa chừng; và {state}, nên một thao tác nhầm vẫn cứu được. Nếu tài khoản của bạn chưa tồn tại trong bản lưu, phiên sẽ mất ở yêu cầu kế tiếp — đó là hành vi mong đợi.',
