  'bak.takeEverything' => 'Mang đi toàn bộ dữ liệu',
  'bak.reversibility' => 'Đây là tính khả hồi: bảo đảm rằng bạn có thể ra đi. Bản sao lưu để quay lại phần mềm này; bản xuất để đi nơi khác. Nó viết bằng JSON, mỗi tệp một bảng, kèm tài liệu, và không cần SQLite hay phần mềm này để đọc lại.',
