  'sec.wizard.againButton' => 'Xem lại trình hướng dẫn',
  'sec.pilotage.intro' => 'Điều hành gom các con số mà ban lãnh đạo nhìn vào: nhân sự, doanh thu, khoản chưa thu, mục tiêu và các kỳ hạn sắp tới. Nó không tính lại gì cả — chỉ tổng hợp những gì các phân hệ khác đã nắm.',
  'sec.personnel.intro' => 'Nhân sự nắm con người: hồ sơ, hợp đồng, nghỉ phép, lịch làm việc, lộ trình nghề nghiệp, sức khỏe và an toàn. Đây là phân hệ có dữ liệu nhạy cảm nhất và cũng được dùng nhiều nhất.',
  'sec.gestion.intro' => 'Quản lý nắm tiền và phương tiện: hóa đơn, báo giá, dự án, đội xe, kho, và kế toán nếu đã mở.',
  'sec.relation.intro' => 'Quan hệ nắm những gì đến từ bên ngoài cũng như bên trong: yêu cầu, phiếu hỗ trợ, cơ sở tri thức, lễ tân, sự kiện và tin tức.',
  'sec.technique.intro' => 'Kỹ thuật nắm chính thực thể này: thiết bị tin học, tích hợp, cập nhật, sao lưu, nhật ký và nhập dữ liệu.',
  'sec.conformite.intro' => 'Tuân thủ nắm những gì bị đòi hỏi: an toàn tài khoản, bảo vệ dữ liệu cá nhân, đời sống pháp lý và chữ ký. Đây là phân hệ được mở vào ngày có thanh tra.',
  'sec.reglages.intro' => 'Thiết lập nắm thực thể: danh tính doanh nghiệp, ngôn ngữ, giao diện, mô-đun và ứng dụng. Phân hệ này không gỡ được — chính nó cho phép đặt lại các phân hệ khác.',
